// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address firstOwner, address secondOwner) public {
        address admin = address(this); // deployer of c in setUp()
        vm.assume(firstOwner != admin);
        vm.assume(secondOwner != admin);
        vm.assume(secondOwner != firstOwner);

        // step 1: admin assigns ownership to a distinct address (succeeds in both P and M)
        vm.prank(admin);
        c.setOwner(firstOwner);

        // step 2: the ADMIN must still be authorized after ownership moved away
        bool ok;
        vm.prank(admin);
        try c.setOwner(secondOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // rule: for any admissible firstOwner/secondOwner, admin's setOwner succeeds
        // and the owner becomes secondOwner; the mutant reverts instead.
        assertTrue(ok && c.owner() == secondOwner);
    }
}
